    function test_all_stringent() result(is_ok)
        logical :: is_ok
        nan = ieee_value(nan, ieee_quiet_nan)
        nfail = 0
        call run()
        is_ok = nfail == 0
        if (is_ok) then
            print '(a)', 'test_all_stringent: ok'
        else
            print '(a, i0, a)', 'test_all_stringent: ', nfail, ' failed'
        end if
    end function

    subroutine compare(name, x, ref)
        character(*), intent(in) :: name
        real(dp), intent(in) :: x(:), ref(:)
        integer :: i
        do i = 1, size(ref)
